import type { TextareaContextType } from "../textarea.types";

import { createContext, useContext } from "react";
export const TextareaContext = createContext<TextareaContextType | null>(null);

export const useTextarea = () => {
  const context = useContext(TextareaContext);
  if (!context) {
    throw new Error(
      "Textarea compound components cannot be rendered outside the Textarea component",
    );
  }
  return context;
};
